import{z as l,x as i,o,c as p,q as s,j as r,D as A,d as e,s as n,S as d,b as E}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"DHCP 与 NAT","description":"","frontmatter":{"title":"DHCP 与 NAT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dhcp-nat.md","filePath":"cs/dhcp-nat.md","lastUpdated":1791413859000}'),B={name:"cs/dhcp-nat.md"};function D(P,a,c,C,T,N){const t=i("Mermaid");return o(),p("div",null,[a[2]||(a[2]=s('<h1 id="dhcp-与-nat" tabindex="-1">DHCP 与 NAT <a class="header-anchor" href="#dhcp-与-nat" aria-label="Permalink to &quot;DHCP 与 NAT&quot;">​</a></h1><div class="epigraph"><p>DHCP 把地址与默认路由租给主机；NAT 让私网多台主机复用少量公网地址，改写 IP 与端口。</p><footer>—— 据 RFC 2131, Dynamic Host Configuration Protocol；RFC 3022, Traditional IP Network Address Translator 整理</footer></div><p><a href="/cs/icmp">上一课</a>假定主机已有地址。<a href="/cs/ip-subnet">IP 编址</a>要每接口一个 IP；手工配置不能规模化，IPv4 公网地址也不够每人一台。缺口是两件配套：<strong>DHCP 租约</strong>与 <strong>NAT 复用</strong>。本课不把 IPv6 地址空间当已解决。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机启动时还没有 IP，不能先打开一个「配置 TCP」。DHCP：发现、提供、请求、确认，在 UDP 广播/中继上完成，交出地址、掩码、网关、DNS（DNS 课再用）。NAT：边界路由器改写私网源地址为公网，用端口区分会话，回包再改回。缺口不是 LPM 公式，而是地址的<strong>获得与改写</strong>。</p><p>本课不把 CGNAT 的全部端口耗尽策略写完。</p><p><span class="marginnote">私网段 RFC 1918：<code>10/8</code>、<code>172.16/12</code>、<code>192.168/16</code>。NAT 破坏「每个地址全球可达」，与端到端论证紧张：新会话难从外向内建。</span></p><p><span class="marginnote">直觉类比：DHCP 像「酒店前台办入住」——你走进大堂广播一句「要房」（Discover），前台递上一张房卡（Offer），你确认要这间（Request），前台登记生效（Ack）。退房时间就是租约，到期不续，房卡（IP）就作废。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DHCP 客户端在 UDP 68，服务器 67；租约到期续租。NAT 表：(协议, 私网 IP, 端口) ↔ (公网 IP, 端口)，对 TCP/UDP 有状态；ICMP 用查询 ID 等。TTL 与校验和随改写重算。ALG 曾修补 FTP 等嵌地址的协议，脆弱，主干不依赖。</p><p><span class="marginnote">数字实例：家里三台设备同时访问 <code>203.0.113.7:443</code>。NAT 把它们分别改写成 <code>198.51.100.1:40001</code>、<code>:40002</code>、<code>:40003</code> 发出去——公网地址只有一个，靠不同源端口区分是谁的会话；回包按端口对号入座，再改回各自的私网地址。</span></p>',11)),(o(),r(d,null,{default:A(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOST%5B%22%E6%97%A0%E5%9C%B0%E5%9D%80%E4%B8%BB%E6%9C%BA%22%5D%20--%3E%20DHCP%5B%22DHCP%20%E7%A7%9F%E7%BA%A6%22%5D%0A%20%20PRIV%5B%22%E7%A7%81%E7%BD%91%E5%88%86%E7%BB%84%22%5D%20--%3E%20NAT%5B%22%E6%94%B9%E5%86%99%E5%9C%B0%E5%9D%80%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20NAT%20--%3E%20WAN%5B%22%E5%85%AC%E7%BD%91%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("DHCP 填好"),E("a",{href:"/cs/ip-subnet"},"子网"),e("课的配置，主机才能 ARP 网关。NAT 让 "),E("a",{href:"/cs/lpm"},"LPM"),e(" 在公网只看见少量前缀，却让传输层五元组在边界被改写——后课 TCP 必须容忍，或应用改用中继。端到端：NAT 是中间盒状态，不是 Saltzer 意义上的「端」。这是后课 QUIC 与 NAT 超时、以及 IPv6 推动的背景。")],-1)),a[5]||(a[5]=E("p",null,"上面那张图画「主机与分组整体往哪流」；这张拆开 DHCP 那一格：一台主机开机时 IP 究竟是经过哪四步对话拿到的，之后又怎么续。",-1)),(o(),r(d,null,{default:A(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%B9%BF%E6%92%AD%20DISCOVER%20%E6%88%91%E8%BF%98%E6%B2%A1%E6%9C%89%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20S%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E5%9B%9E%20OFFER%20%E6%8F%90%E8%AE%AE%E4%B8%80%E4%B8%AA%E5%9C%B0%E5%9D%80%22%5D%0A%20%20S%20--%3E%20C2%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E5%B9%BF%E6%92%AD%20REQUEST%20%E6%88%91%E8%A6%81%E8%BF%99%E4%B8%AA%22%5D%0A%20%20C2%20--%3E%20S2%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%20ACK%20%E6%AD%A3%E5%BC%8F%E7%A7%9F%E7%BB%99%E4%BD%A0%20%E5%B9%B6%E5%B8%A6%E7%BD%91%E5%85%B3%20DNS%22%5D%0A%20%20S2%20--%3E%20USE%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E9%85%8D%E7%BD%AE%E5%A5%BD%20%E5%BC%80%E5%A7%8B%E4%B8%8A%E7%BD%91%22%5D%0A%20%20USE%20--%3E%20REN%5B%22%E7%A7%9F%E7%BA%A6%E8%BF%87%E5%8D%8A%20%E5%8F%91%20REQUEST%20%E7%BB%AD%E7%A7%9F%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：以为电脑「有 IP 就能被外网直接访问」。私网地址（如 <code>192.168.1.5</code>）在公网路由表里根本不可达，外网主动连进来会卡在 NAT——查不到对应表项就无处转发。所以 P2P 联机才需要打洞或中继来帮忙。</span></p><p>与<a href="/cs/process-image">进程</a>无关：改写发生在路由器，主机套接字仍绑定私网地址。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DHCP 欺骗写成攻击教程。不引入 IPsec 穿越 NAT 的全部封装。IPv6 用 SLAAC/DHCPv6，对照下一课；不要把 NAT66 当 IPv6 的必经之路。</p><p>中继代理让服务器不在广播域内。NAT 对分片重组的依赖是实现地雷，主干假定不分片或先重组再改写。</p><p>租约续期失败则地址应停止使用；NAT 表项超时则内网会话静默断开。</p><p>后课默认：IPv4 常靠 DHCP 与 NAT 撑着。地址长度与邻居发现如何换一套，下一课 IPv6 对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DHCP（RFC 2131）租地址与网关；NAT（RFC 3022）复用公网地址。</li><li>NAT 改写五元组，削弱端到端可达。</li><li>IPv6 用更大地址空间对照，下一课。</li><li>出处：RFC 2131；RFC 3022；RFC 1918；Kurose and Ross。</li></ul>',9))])}const f=l(B,[["render",D]]);export{m as __pageData,f as default};
